1661:       // Draw Wavy Golden Alkaline Noodles (Chijire-men) with Subsurface Broth Depth & Wet Specular Sheen
1662:       function drawNoodles(c, time, lightX, lightY) {
1663:         c.save();
1664:         const bRx = R * 0.88;
1665:         const bRy = bRx * ASPECT;
1666:         const bCy = R * 0.055;
1667:         traceEllipsePath(c, 0, bCy, bRx, bRy, false, 72);
1668:         c.clip();
1669: 
1670:         // Warm subsurface ambient shadow under the noodle mound
1671:         const moundShadow = c.createRadialGradient(-18, 28, 15, -10, 28, R * 0.58);
1672:         moundShadow.addColorStop(0, 'rgba(72, 18, 2, 0.52)');
1673:         moundShadow.addColorStop(0.65, 'rgba(85, 24, 3, 0.25)');
1674:         moundShadow.addColorStop(1, 'rgba(85, 24, 3, 0)');
1675:         c.fillStyle = moundShadow;
1676:         c.beginPath();
1677:         c.ellipse(-12, 26, R * 0.58, R * 0.36, 0, 0, Math.PI * 2);
1678:         c.fill();
1679: 
1680:         const animPhase = reducedMotion ? 0 : time * 1.35;
1681: 
1682:         for (let i = 0; i < noodleStrands.length; i++) {
1683:           const ns = noodleStrands[i];
1684:           const steps = 22;
1685:           const pts = [];
1686: 
1687:           const dx = ns.endX - ns.startX;
1688:           const dy = ns.endY - ns.startY;
1689:           const len = Math.hypot(dx, dy) || 1;
1690:           const nx = -dy / len;
1691:           const ny = dx / len;
1692: 
1693:           for (let s = 0; s <= steps; s++) {
1694:             const t = s / steps;
1695:             const env = Math.sin(t * Math.PI); // tapers at submerged ends
1696:             const wave = Math.sin(t * ns.waveFreq * Math.PI + ns.phase + animPhase * 0.35) * ns.waveAmp * env;
1697:             const archOffset = Math.sin(t * Math.PI) * ns.arch;
1698:             const px = lerp(ns.startX, ns.endX, t) + nx * (wave + archOffset * 0.35);
1699:             const py = lerp(ns.startY, ns.endY, t) + ny * (wave * 0.72 + archOffset * 0.65);
1700:             pts.push({ x: px, y: py });
1701:           }
1702: 
1703:           const traceStrand = (offsetX = 0, offsetY = 0) => {
1704:             c.beginPath();
1705:             c.moveTo(pts[0].x + offsetX, pts[0].y + offsetY);
1706:             for (let s = 1; s < pts.length - 1; s++) {
1707:               const xc = (pts[s].x + pts[s + 1].x) * 0.5 + offsetX;
1708:               const yc = (pts[s].y + pts[s + 1].y) * 0.5 + offsetY;
1709:               c.quadraticCurveTo(pts[s].x + offsetX, pts[s].y + offsetY, xc, yc);
1710:             }
1711:             const last = pts[pts.length - 1];
1712:             c.lineTo(last.x + offsetX, last.y + offsetY);
1713:           };
1714: 
1715:           c.lineCap = 'round';
1716:           c.lineJoin = 'round';
1717: 
1718:           // 1. Deep broth-submerged shadow/border
1719:           traceStrand(1.2, 2.6);
1720:           c.strokeStyle = `rgba(92, 26, 3, ${0.42 + (1 - ns.depth) * 0.25})`;
1721:           c.lineWidth = ns.thickness + 3.2;
1722:           c.stroke();
1723: 
1724:           // 2. Golden alkaline noodle body
1725:           traceStrand(0, 0);
1726:           const nGrad = c.createLinearGradient(ns.startX, ns.startY, ns.endX, ns.endY);
1727:           const bright = 0.72 + ns.depth * 0.28;
1728:           const rCol = Math.round(238 * bright);
1729:           const gCol = Math.round(182 * bright);
1730:           const bCol = Math.round(76 * bright);
1731:           nGrad.addColorStop(0, 'rgba(182, 92, 22, 0.45)');
1732:           nGrad.addColorStop(0.2, `rgb(${rCol - 18}, ${gCol - 24}, ${bCol - 18})`);
1733:           nGrad.addColorStop(0.5, `rgb(${Math.min(255, rCol + 12)}, ${Math.min(255, gCol + 16)}, ${Math.min(255, bCol + 22)})`);
1734:           nGrad.addColorStop(0.8, `rgb(${rCol - 14}, ${gCol - 20}, ${bCol - 14})`);
1735:           nGrad.addColorStop(1, 'rgba(175, 86, 18, 0.45)');
1736:           c.strokeStyle = nGrad;
1737:           c.lineWidth = ns.thickness;
1738:           c.stroke();
1739: 
1740:           // 3. Wet glossy specular highlight along top-left noodle crest (for emergent strands)
1741:           if (ns.depth > 0.32) {
1742:             traceStrand(-0.8 + lightX * 1.1, -1.3 + lightY * 0.9);
1743:             const specAlpha = (ns.depth - 0.3) * 0.68;
1744:             const specGrad = c.createLinearGradient(ns.startX, ns.startY, ns.endX, ns.endY);
1745:             specGrad.addColorStop(0, 'rgba(255, 248, 225, 0)');
1746:             specGrad.addColorStop(0.28, `rgba(255, 248, 225, ${specAlpha * 0.7})`);
1747:             specGrad.addColorStop(0.52, `rgba(255, 252, 240, ${specAlpha})`);
1748:             specGrad.addColorStop(0.74, `rgba(255, 244, 215, ${specAlpha * 0.65})`);
1749:             specGrad.addColorStop(1, 'rgba(255, 248, 225, 0)');
1750:             c.strokeStyle = specGrad;
1751:             c.lineWidth = ns.thickness * 0.26;
1752:             c.stroke();
1753:           }
1754:         }
1755: 
1756:         c.restore();
1757:       }
