1686:       // Draw Wavy Golden Alkaline Noodles (Chijire-men) with Subsurface Broth Depth & Wet Specular Sheen
1687:       function drawNoodles(c, time, lightX, lightY) {
1688:         c.save();
1689:         const bRx = R * 0.88;
1690:         const bRy = bRx * ASPECT;
1691:         const bCy = R * 0.055;
1692:         traceEllipsePath(c, 0, bCy, bRx, bRy, false, 72);
1693:         c.clip();
1694: 
1695:         // Warm subsurface ambient shadow under the noodle mound
1696:         const moundShadow = c.createRadialGradient(-18, 28, 15, -10, 28, R * 0.58);
1697:         moundShadow.addColorStop(0, 'rgba(72, 18, 2, 0.52)');
1698:         moundShadow.addColorStop(0.65, 'rgba(85, 24, 3, 0.25)');
1699:         moundShadow.addColorStop(1, 'rgba(85, 24, 3, 0)');
1700:         c.fillStyle = moundShadow;
1701:         c.beginPath();
1702:         c.ellipse(-12, 26, R * 0.58, R * 0.36, 0, 0, Math.PI * 2);
1703:         c.fill();
1704: 
1705:         const animPhase = reducedMotion ? 0 : time * 1.35;
1706: 
1707:         for (let i = 0; i < noodleStrands.length; i++) {
1708:           const ns = noodleStrands[i];
1709:           const steps = 22;
1710:           const pts = [];
1711: 
1712:           const dx = ns.endX - ns.startX;
1713:           const dy = ns.endY - ns.startY;
1714:           const len = Math.hypot(dx, dy) || 1;
1715:           const nx = -dy / len;
1716:           const ny = dx / len;
1717: 
1718:           for (let s = 0; s <= steps; s++) {
1719:             const t = s / steps;
1720:             const env = Math.sin(t * Math.PI); // tapers at submerged ends
1721:             const wave = Math.sin(t * ns.waveFreq * Math.PI + ns.phase + animPhase * 0.35) * ns.waveAmp * env;
1722:             const archOffset = Math.sin(t * Math.PI) * ns.arch;
1723:             const px = lerp(ns.startX, ns.endX, t) + nx * (wave + archOffset * 0.35);
1724:             const py = lerp(ns.startY, ns.endY, t) + ny * (wave * 0.72 + archOffset * 0.65);
1725:             pts.push({ x: px, y: py });
1726:           }
1727: 
1728:           const traceStrand = (offsetX = 0, offsetY = 0) => {
1729:             c.beginPath();
1730:             c.moveTo(pts[0].x + offsetX, pts[0].y + offsetY);
1731:             for (let s = 1; s < pts.length - 1; s++) {
1732:               const xc = (pts[s].x + pts[s + 1].x) * 0.5 + offsetX;
1733:               const yc = (pts[s].y + pts[s + 1].y) * 0.5 + offsetY;
1734:               c.quadraticCurveTo(pts[s].x + offsetX, pts[s].y + offsetY, xc, yc);
1735:             }
1736:             const last = pts[pts.length - 1];
1737:             c.lineTo(last.x + offsetX, last.y + offsetY);
1738:           };
1739: 
1740:           c.lineCap = 'round';
1741:           c.lineJoin = 'round';
1742: 
1743:           // 1. Deep broth-submerged shadow/border
1744:           traceStrand(1.2, 2.6);
1745:           c.strokeStyle = `rgba(92, 26, 3, ${0.42 + (1 - ns.depth) * 0.25})`;
1746:           c.lineWidth = ns.thickness + 3.2;
1747:           c.stroke();
1748: 
1749:           // 2. Golden alkaline noodle body
1750:           traceStrand(0, 0);
1751:           const nGrad = c.createLinearGradient(ns.startX, ns.startY, ns.endX, ns.endY);
1752:           const bright = 0.72 + ns.depth * 0.28;
1753:           const rCol = Math.round(238 * bright);
1754:           const gCol = Math.round(182 * bright);
1755:           const bCol = Math.round(76 * bright);
1756:           nGrad.addColorStop(0, 'rgba(182, 92, 22, 0.45)');
1757:           nGrad.addColorStop(0.2, `rgb(${rCol - 18}, ${gCol - 24}, ${bCol - 18})`);
1758:           nGrad.addColorStop(0.5, `rgb(${Math.min(255, rCol + 12)}, ${Math.min(255, gCol + 16)}, ${Math.min(255, bCol + 22)})`);
1759:           nGrad.addColorStop(0.8, `rgb(${rCol - 14}, ${gCol - 20}, ${bCol - 14})`);
1760:           nGrad.addColorStop(1, 'rgba(175, 86, 18, 0.45)');
1761:           c.strokeStyle = nGrad;
1762:           c.lineWidth = ns.thickness;
1763:           c.stroke();
1764: 
1765:           // 3. Wet glossy specular highlight along top-left noodle crest (for emergent strands)
1766:           if (ns.depth > 0.32) {
1767:             traceStrand(-0.8 + lightX * 1.1, -1.3 + lightY * 0.9);
1768:             const specAlpha = (ns.depth - 0.3) * 0.68;
1769:             const specGrad = c.createLinearGradient(ns.startX, ns.startY, ns.endX, ns.endY);
1770:             specGrad.addColorStop(0, 'rgba(255, 248, 225, 0)');
1771:             specGrad.addColorStop(0.28, `rgba(255, 248, 225, ${specAlpha * 0.7})`);
1772:             specGrad.addColorStop(0.52, `rgba(255, 252, 240, ${specAlpha})`);
1773:             specGrad.addColorStop(0.74, `rgba(255, 244, 215, ${specAlpha * 0.65})`);
1774:             specGrad.addColorStop(1, 'rgba(255, 248, 225, 0)');
1775:             c.strokeStyle = specGrad;
1776:             c.lineWidth = ns.thickness * 0.26;
1777:             c.stroke();
1778:           }
1779:         }
1780: 
1781:         c.restore();
1782:       }
