// Build Soy-Marinated Vegan Jammy "Ajitama" Halves Layer
function buildAjitamaLayer() {
  const can = document.createElement('canvas');
  can.width = 460;
  can.height = 340;
  const c = can.getContext('2d');
  c.translate(230, 170);

  const halves = [
    { x: -88, y: 36, rot: -0.24, scale: 1.0 },
    { x: 58, y: 8, rot: 0.19, scale: 0.96 }
  ];

  // Helper for natural ovate egg silhouette (tapered at left apex, fuller at right yolk end)
  const traceOvateEgg = (ctx2, yOffset, rx, ry) => {
    ctx2.beginPath();
    const steps = 48;
    for (let i = 0; i <= steps; i++) {
      const a = (i / steps) * Math.PI * 2;
      const ca = Math.cos(a);
      const sa = Math.sin(a);
      const taper = 1 + 0.14 * ca;
      const px = ca * rx;
      const py = yOffset + sa * ry * taper;
      if (i === 0) ctx2.moveTo(px, py);
      else ctx2.lineTo(px, py);
    }
    ctx2.closePath();
  };

  halves.forEach((h) => {
    c.save();
    c.translate(h.x, h.y);
    c.rotate(h.rot);
    c.scale(h.scale, h.scale);

    const rx = 45;
    const ry = 33;

    // Deep warm broth shadow
    c.fillStyle = 'rgba(25, 6, 1, 0.62)';
    traceOvateEgg(c, 12, rx * 1.08, ry * 1.1);
    c.fill();

    // 3D soy-marinated outer dome underside
    const domeGrad = c.createLinearGradient(-rx, 0, rx, 14);
    domeGrad.addColorStop(0, '#59290c');
    domeGrad.addColorStop(0.35, '#9e5422');
    domeGrad.addColorStop(0.75, '#783912');
    domeGrad.addColorStop(1, '#421b06');
    c.fillStyle = domeGrad;
    traceOvateEgg(c, 8.5, rx * 1.01, ry * 1.03);
    c.fill();

    // Cut top face: Soy-tare stained edge fading into silky ivory plant-curd white
    const whiteGrad = c.createRadialGradient(-2, -2, rx * 0.34, 0, 0, rx * 1.02);
    whiteGrad.addColorStop(0, '#fff9ee');
    whiteGrad.addColorStop(0.56, '#f7ebd4');
    whiteGrad.addColorStop(0.82, '#d9ab76');
    whiteGrad.addColorStop(0.94, '#9c5623');
    whiteGrad.addColorStop(1, '#66310e');
    c.fillStyle = whiteGrad;
    traceOvateEgg(c, 0, rx, ry);
    c.fill();

    // Jammy, molten saffron-persimmon yolk center (shifted slightly toward fuller end)
    const yRx = rx * 0.56;
    const yRy = ry * 0.58;
    const yolkGrad = c.createRadialGradient(-2, -4, 2, 4, 1, yRx * 1.06);
    yolkGrad.addColorStop(0, '#ffaa38');
    yolkGrad.addColorStop(0.36, '#f55d08');
    yolkGrad.addColorStop(0.76, '#cc3202');
    yolkGrad.addColorStop(1, '#941f00');
    c.fillStyle = yolkGrad;
    c.beginPath();
    c.ellipse(5, 0.5, yRx, yRy, 0, 0, Math.PI * 2);
    c.fill();

    // Viscous jammy ring & glossy liquid highlight on yolk
    c.strokeStyle = 'rgba(255, 198, 98, 0.48)';
    c.lineWidth = 1.6;
    c.beginPath();
    c.ellipse(5, 0.5, yRx * 0.84, yRy * 0.84, 0, Math.PI * 0.9, Math.PI * 1.88);
    c.stroke();

    // Crisp wet specular crescent on molten center
    c.fillStyle = 'rgba(255, 248, 228, 0.84)';
    c.beginPath();
    c.ellipse(-3, -5.5, 8.8, 3.8, -0.32, 0, Math.PI * 2);
    c.fill();
    c.beginPath();
    c.arc(9, -3, 2.3, 0, Math.PI * 2);
    c.fill();

    // Wet broth meniscus around the base of the half
    c.strokeStyle = 'rgba(235, 132, 34, 0.46)';
    c.lineWidth = 2.4;
    c.beginPath();
    c.ellipse(0, 7.5, rx * 1.01, ry * 1.02, 0, 0.15, Math.PI - 0.15);
    c.stroke();

    c.restore();
  });

  return can;
}

