2158:       // Update Physics for Broth Ripples, Floating Chili Oil & Volumetric Steam
2159:       function updateSimulation(time, dt) {
2160:         // Smooth pointer interpolation
2161:         pointer.x += (pointer.targetX - pointer.x) * Math.min(1, dt * 8);
2162:         pointer.y += (pointer.targetY - pointer.y) * Math.min(1, dt * 8);
2163:         pointer.vx *= 0.9;
2164:         pointer.vy *= 0.9;
2165: 
2166:         // Spring decay for topping buoyancy impulse (on click/tap)
2167:         if (pointer.bobImpulse > 0.001) {
2168:           pointer.bobImpulse *= Math.exp(-dt * 2.8);
2169:           pointer.bobPhase += dt * 11;
2170:         } else {
2171:           pointer.bobImpulse = 0;
2172:         }
2173: 
2174:         // Autonomous gentle simmer ripples
2175:         if (!reducedMotion && Math.random() < dt * 1.4 && ripples.length < 10) {
2176:           const ang = Math.random() * Math.PI * 2;
2177:           const dist = Math.random() * R * 0.62;
2178:           ripples.push({
2179:             x: Math.cos(ang) * dist,
2180:             y: R * 0.055 + Math.sin(ang) * dist * ASPECT,
2181:             minR: 4,
2182:             maxR: 48 + Math.random() * 45,
2183:             age: 0,
2184:             maxAge: 2.2 + Math.random() * 1.2,
2185:             strength: 0.45 + Math.random() * 0.35
2186:           });
2187:         }
2188: 
2189:         for (let i = ripples.length - 1; i >= 0; i--) {
2190:           ripples[i].age += dt;
2191:           if (ripples[i].age >= ripples[i].maxAge) {
2192:             ripples.splice(i, 1);
2193:           }
2194:         }
2195: 
2196:         // Update Floating Chili Oil Pearls (Rayu) & Garnish
2197:         const bRx = R * 0.84;
2198:         const bRy = bRx * ASPECT;
2199:         const bCy = R * 0.055;
2200: 
2201:         for (let i = 0; i < chiliDroplets.length; i++) {
2202:           const d = chiliDroplets[i];
2203:           if (!reducedMotion) {
2204:             // Subtle thermal convection swirl
2205:             const swirlX = Math.cos(time * 0.55 + d.phase) * 0.14;
2206:             const swirlY = Math.sin(time * 0.45 + d.phase) * 0.09;
2207:             d.vx += swirlX * dt * 15;
2208:             d.vy += swirlY * dt * 15;
2209:           }
2210: 
2211:           // Interactive cursor stirring in broth
2212:           if (pointer.active && pointer.inBowl) {
2213:             const dx = d.x - pointer.virtualX;
2214:             const dy = (d.y - pointer.virtualY) / ASPECT;
2215:             const distSq = dx * dx + dy * dy;
2216:             const interactRad = 105;
2217:             if (distSq < interactRad * interactRad && distSq > 1) {
2218:               const dist = Math.sqrt(distSq);
2219:               const falloff = (1 - dist / interactRad);
2220:               // Push radially + impart pointer velocity swirl
2221:               d.vx += ((dx / dist) * 28 + pointer.vx * 0.45) * falloff * dt;
2222:               d.vy += ((dy / dist) * 18 + pointer.vy * 0.45) * falloff * dt;
2223:             }
2224:           }
2225: 
2226:           // Gentle spring return toward home pocket so broth stays balanced
2227:           d.vx += (d.homeX - d.x) * 0.65 * dt;
2228:           d.vy += (d.homeY - d.y) * 0.65 * dt;
2229: 
2230:           d.vx *= 0.92;
2231:           d.vy *= 0.92;
2232:           d.x += d.vx;
2233:           d.y += d.vy;
