// 2. Silky Variable-Width Steam Ribbons rising and billowing into the dark air
for (let i = 0; i < steamPlumes.length; i++) {
  const pl = steamPlumes[i];
  const nodes = pl.nodes;
  const nLen = nodes.length;
  const topNode = nodes[nLen - 1];

  // Two passes per plume: wide soft outer vapor hull + delicate inner core filament
  for (let pass = 0; pass < 2; pass++) {
    const widthMult = pass === 0 ? 1.15 : 0.38;
    const leftPts = [];
    const rightPts = [];

    for (let j = 0; j < nLen; j++) {
      const frac = j / (nLen - 1);
      const prev = nodes[Math.max(0, j - 1)];
      const next = nodes[Math.min(nLen - 1, j + 1)];
      let tx = next.x - prev.x;
      let ty = next.y - prev.y;
      const tLen = Math.hypot(tx, ty) || 1;
      tx /= tLen;
      ty /= tLen;
      const nx = -ty;
      const ny = tx;

      // Starts narrow at broth surface, billows wider as it rises, tapers softly at top
      const profile = Math.sin(frac * Math.PI) * (0.32 + Math.pow(frac, 0.75) * 1.45);
      const halfW = pl.widthBase * widthMult * profile;

      leftPts.push({ x: nodes[j].x + nx * halfW, y: nodes[j].y + ny * halfW });
      rightPts.push({ x: nodes[j].x - nx * halfW, y: nodes[j].y - ny * halfW });
    }

    c.beginPath();
    c.moveTo(leftPts[0].x, leftPts[0].y);
    for (let j = 1; j < nLen - 1; j++) {
      const xc = (leftPts[j].x + leftPts[j + 1].x) * 0.5;
      const yc = (leftPts[j].y + leftPts[j + 1].y) * 0.5;
      c.quadraticCurveTo(leftPts[j].x, leftPts[j].y, xc, yc);
    }
    c.lineTo(leftPts[nLen - 1].x, leftPts[nLen - 1].y);
    c.lineTo(rightPts[nLen - 1].x, rightPts[nLen - 1].y);
    for (let j = nLen - 2; j >= 1; j--) {
      const xc = (rightPts[j].x + rightPts[j - 1].x) * 0.5;
      const yc = (rightPts[j].y + rightPts[j - 1].y) * 0.5;
      c.quadraticCurveTo(rightPts[j].x, rightPts[j].y, xc, yc);
    }
    c.closePath();

    const alphaScale = pass === 0 ? 1.0 : 0.78;
    const a = pl.alpha * alphaScale;
    const sGrad = c.createLinearGradient(pl.baseX, pl.baseY, topNode.x, topNode.y);
    sGrad.addColorStop(0, 'rgba(255, 212, 168, 0)');
    sGrad.addColorStop(0.15, `rgba(255, 224, 188, ${a * 1.15})`);
    sGrad.addColorStop(0.48, `rgba(248, 232, 214, ${a})`);
    sGrad.addColorStop(0.82, `rgba(225, 222, 228, ${a * 0.45})`);
    sGrad.addColorStop(1, 'rgba(215, 215, 225, 0)');

    c.fillStyle = sGrad;
    c.fill();
  }
}

